    {
      "card_ids": ["C06"],
      "claim": "Human PET imaging with [11C]CURB showed rapid and high brain uptake after systemic administration, directly supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "JNJ-5207852 crossed the blood-brain barrier after subcutaneous dosing and reached high, persistent brain concentrations measured by liquid chromatography, supporting meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "N-methyl analogues 15b and 15c showed poor brain-to-blood ratios in rats, providing a contradictory signal for CNS access in a related analogue set.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple direct in-vivo studies in humans, rats, monkeys, and mice demonstrate brain uptake and BBB penetration for structurally related compounds; the few negative reports come from less similar or peripheral chemotypes and are outweighed by the positive direct evidence.",
  "evidence_gaps": [
    "No direct query-specific experimental data are available; all evidence is from analogues with Morgan similarity below 0.35.",
    "One related N-methyl analogue set showed poor brain-to-blood ratio, and roxatidine showed low CSF exposure, introducing some uncertainty.",
    "Some records lack detailed dose, route, and time information, limiting full condition matching."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

